import pytesseract
from PIL import Image

files = ['/app/workspace/dataset/img/087.jpg', '/app/workspace/dataset/img/088.jpg']

for f in files:
    print(f"--- {f} ---")
    for psm in [4, 6, 11, 12]:
        print(f"PSM {psm}:")
        try:
            text = pytesseract.image_to_string(Image.open(f), config=f'--psm {psm}')
            # Print only lines with numbers or Date
            for line in text.split('\n'):
                if '201' in line or 'Date' in line or 'Slip' in line or '/' in line:
                    print(line)
        except:
            print("Error")
